const demoFonts=[['霞鹜文楷','LXGW WenKai','song','开源 / SIL OFL'],['思源黑体','Source Han Sans','hei','开源 / OFL'],['朱雀仿宋','Zhuque Fangsong','song','免费商用'],['寒蝉全圆体','Cubic 11','display','免费商用'],['得意黑','Smiley Sans','display','开源 / OFL'],['仓耳今楷','CangEr JinKai','hand','免费商用']];
const grid=document.querySelector('#fontGrid'),search=document.querySelector('#search'),preview=document.querySelector('#previewText'),labels={song:'宋体',hei:'黑体',hand:'手写',display:'艺术',楷体:'楷体','手绘体':'手写','艺术体':'艺术'};let fonts=[],filter='all',limit=18,activeFont=null;
const normalize=(item,index)=>({name:item.name||item.familyName||`未命名字体 ${index+1}`,en:item.familyName||item.fullName||'Open Font',type:item.type||'display',license:item.license||'授权以作者说明为准',size:item.size||'—',path:item.path||''});
function cdnUrl(path){return `https://cdn.jsdelivr.net/gh/jaywcjlove/free-font@main/${path.split('/').map(encodeURIComponent).join('/')}`}
function loadFont(font){if(!font.path)return;const family=`Specimen-${fonts.indexOf(font)}`;if(document.getElementById(family))return family;const style=document.createElement('style');style.id=family;style.textContent=`@font-face{font-family:'${family}';src:url('${cdnUrl(font.path)}') format('truetype');font-display:swap}`;document.head.append(style);return family}
function render(){const q=search.value.trim().toLowerCase(),items=fonts.filter(f=>(filter==='all'||f.type===filter)&&(!q||f.name.toLowerCase().includes(q)||f.en.toLowerCase().includes(q))).slice(0,limit);grid.innerHTML=items.map(f=>{const family=activeFont===f?loadFont(f):'';return `<article class="font-card${activeFont===f?' selected':''}" data-index="${fonts.indexOf(f)}" tabindex="0"><div class="card-top"><span class="tag">${labels[f.type]||f.type||'字体'}</span><button class="favorite" aria-label="收藏 ${f.name}">♡</button></div><div class="specimen" style="font-family:${family?`'${family}'`:'var(--serif)'}">${preview.value||'春风得意马蹄疾'}</div><div class="font-name">${f.name}</div><div class="font-meta">${f.en}　·　${f.size}</div><div class="card-foot"><span>${f.license}</span><span>${activeFont===f?'CDN 已加载':'点击试读'}</span></div></article>`}).join('');document.querySelector('#empty').style.display=items.length?'none':'block';document.querySelector('#loadMore').style.display=items.length<fonts.filter(f=>filter==='all'||f.type===filter).length?'block':'none';document.querySelectorAll('.font-card').forEach(card=>{card.onclick=e=>{if(e.target.closest('.favorite'))return;activeFont=fonts[Number(card.dataset.index)];loadFont(activeFont);render()};card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();card.click()}}});document.querySelectorAll('.favorite').forEach(b=>b.onclick=()=>{b.classList.toggle('saved');b.textContent=b.classList.contains('saved')?'♥':'♡'});}
async function init(){try{const response=await fetch('data.json');if(!response.ok)throw new Error('data');fonts=(await response.json()).map(normalize)}catch{fonts=demoFonts.map(([name,en,type,license])=>({name,en,type,license,size:'—',path:''}))}render()}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelector('.tab.active').classList.remove('active');b.classList.add('active');filter=b.dataset.filter;limit=18;render()});search.oninput=()=>{limit=18;render()};preview.oninput=render;document.querySelector('#clearPreview').onclick=()=>{preview.value='春风得意马蹄疾  ·  Hello, world!';render()};document.querySelector('#loadMore').onclick=()=>{limit+=18;render()};document.querySelectorAll('.view').forEach(b=>b.onclick=()=>{document.querySelector('.view.active').classList.remove('active');b.classList.add('active');grid.style.gridTemplateColumns=b.dataset.view==='list'?'1fr':''});document.querySelector('#themeToggle').onclick=()=>document.body.classList.toggle('dark');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();search.focus()}});init();
